update country_flag_history set image_url = '/flags/history/tr-0000.svg' where id = 2282 and iso_code = 'tr';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('tr', '/flags/history/tr-1844.svg', '1844-01-01', '1923-10-29', 'Empire ottoman (1844-1923)', 'Ottoman Empire (1844–1923)', 'Avec les réformes du Tanzimat, l''étoile à cinq branches remplace en 1844 celle à huit branches ; la République de Turquie conserve ce drapeau et fixe ses proportions en 1936.', 'With the Tanzimat reforms, the five-pointed star replaced the eight-pointed one in 1844; the Republic of Turkey kept this flag and fixed its proportions in 1936.');
